  SchoolConfig_1_Name = {Text = "Хаос"},
  SchoolConfig_1_SchoolBattleTips_1 = {
    Text = "·Резонанс Серебрянного ключа: в конце хода получить 250 очков Ключесвета. После использования Воспоминания все Пробуждённые получают <BlueQuality:[Arg1]> очков Алиемуса. При втором использовании Воспоминания вместо этого освободите \"Незабвенный рассвет\": выберите 1 разблокированное Призыв и активируйте его 2 раза, каждое разблокированное Призыв можно выбрать только 1 раз в этом исследовании, нельзя выбирать изначально имеющееся Призыв."
