  SchoolConfig_3_Tips = {
    Text = "·Межпространственный Переход: после розыгрыша первой карты команды в каждом ходу временная Копия её исходной версии помещается в Ультра пространство, Эффект не может быть активирован в сверхпространственном ходе.\n·Сверхпространственный ход: после входа в сверхпространственный ход все карты из сверхпространства помещаются в руку вместо вытягивания карты. Урон, щиты, восстановление жизней, ключесвет, безумие, изменения силы, яд, Контратака и кровотечение, вызванные сверхпространственным ходом, уменьшаются на 25%.\n·Аннигиляция: раз за ход можно удалить карту с самой левой стороны сверхпространства и добавить 1 карту «Озарение» в руку.\n·Мастерство Ультра: за каждую единицу мастерства царства в команде в начале хода есть 0.125% шанс получить 1 карту «Озарение», если вероятность превышает 100%, можно получить несколько карт.\n·Чистейшее сверхизмерение: если в команде состоят только пробуждённые сверхизмерения, Эффект свойства сверхизмеренной мастерства удваивается и больше не подвержен эффекту снижения способностей сверхпространственного хода."
  },
  SchoolConfig_4_Name = {Text = "Эквор"},
  SchoolConfig_4_SchoolBattleTips_1 = {
    Text = "·Поза щупальца: в начале хода базовая поза «Прилив», в позе «Прилив» можно нажать на щупальца, чтобы переключиться на позу «Тихое море» или «Девятый вал». Если в конце хода вы все еще находитесь в позе «Прилив», в начале следующего хода создается 1 щупальце. \n ·Сбор щупалец: после пробуждения тела с помощью взрыва безумия получаете 1 Уровень сбора щупалец, с шансом <BlueQuality:[Arg5]％> дополнительно получить 1 Уровень сбора щупалец. В конце хода за каждое щупальце сбора щупалец 1 щупальце атакует передних врагов, после чего сбросьте сбор щупалец. \n ·Критический шанс щупалец: <BlueQuality:[Arg6]％>. \n ·Критический Урон щупалец: <BlueQuality:[Arg7]％>. \n ·Переполнение щупалец: после постоянного превышения максимального количества щупалец, 1 щупальце атакует 3 раза и увеличивает максимальное количество щупалец на 1, каждый раз, когда срабатывает этот Эффект, количество раз, необходимое для увеличения максимального количества щупалец, увеличивается на 1."
  },
  SchoolConfig_4_SchoolBattleTips_2 = {
    Text = "·Стойка щупалец: в начале хода базовая поза «Волны прибоя».\n·В позе «Волны прибоя» можно нажать на щупальца, чтобы переключиться на позу «Спокойное море» или «Девятый вал», каждая из которых имеет перезарядку в 3 хода. Если в конце хода вы все еще находитесь в позе «Волны прибоя», в начале следующего хода создается 1 щупальце.\n·Мастерство царства изменяется на «Бентос: Мастерство Эквор», больше не имеет эффекта «Скопление щупалец», каждая единица мастерства царства увеличивает щит «Бентос: Спокойное море» на 0.025% от макс. ОЗ и дополнительно увеличивает урон щупалец «Бентос: Девятый вал» на 0.025%. Если команда состоит из Эквор или Хаос Пробуждённых, эффект «Бентос: Мастерство царства» удваивается.\n·Крит. шанс щупальцем: <BlueQuality:[Arg3]%>.\n·Крит. урон щупальцем: <BlueQuality:[Arg4]%>.\n·Переполнение щупалец: после того как количество постоянных щупалец превышает лимит, 1 щупальце атакует 3 раза и увеличивает лимит щупалец на 1, каждое срабатывание этого эффекта увеличивает количество необходимых срабатываний для повышения лимита щупалец на 1."
